    MYSQL_TYPE_BLOB = 252,
    MYSQL_TYPE_VAR_STRING = 253,
    MYSQL_TYPE_STRING = 254,
    MYSQL_TYPE_GEOMETRY = 255,
    _,
    pub fn get(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn has(__cp_s: []const u8) bool { return std.meta.stringToEnum(@This(), __cp_s) != null; }
    pub fn fromName(__cp_s: []const u8) ?@This() { return std.meta.stringToEnum(@This(), __cp_s); }
    pub fn name(__cp_self: @This()) []const u8 { return @tagName(__cp_self); }

pub fn isBinaryFormatSupported(self: FieldType) bool {
            return (switch (self) {
.MYSQL_TYPE_TINY, .MYSQL_TYPE_SHORT, .MYSQL_TYPE_LONG, .MYSQL_TYPE_LONGLONG, .MYSQL_TYPE_FLOAT, .MYSQL_TYPE_DOUBLE, .MYSQL_TYPE_TIME, .MYSQL_TYPE_DATE, .MYSQL_TYPE_DATETIME, .MYSQL_TYPE_TIMESTAMP => true,
else => false,
});
    }
    
    pub const fromJS = MySQLValue.fieldTypeFromJS;
};

pub const Value = MySQLValue.Value;
pub const int1 = u8;
pub const int2 = u16;
pub const int3 = u24;
pub const int4 = u32;
pub const int8 = u64;
pub const MySQLInt8 = int1;
pub const MySQLInt16 = int2;
pub const MySQLInt24 = int3;
pub const MySQLInt32 = int4;
pub const MySQLInt64 = int8;
